INSERT INTO `subtopics` VALUES (175,31,'Introduction to Python Programming','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Python is a readable, general-purpose language used for software, automation, websites, data, and artificial intelligence.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A Python program is a sequence of instructions. The interpreter reads those instructions and performs them in order. Start by naming the task, writing the smallest steps, and checking the result.</p><h4>Worked example</h4><pre><code>message = &#x27;Hello, Python!&#x27;\nprint(message)</code></pre></section>\n<section><h3>Try it</h3><p>Change the message and print a second line that describes one task a computer could automate.</p><p><strong>Learning check:</strong> Run a short script and explain that print displays a value.</p></section>\n</article>',1,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(176,31,'Python Installation','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Install Python and choose an editor or IDE. Verify the setup by running a simple program.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>The Python interpreter runs source files. An editor helps you write them, but the two tools are separate. Check that your terminal can find the interpreter before troubleshooting an editor.</p><h4>Worked example</h4><pre><code># In a terminal, check the interpreter\npython --version\n\n# Save this as hello.py, then run: python hello.py\nprint(&#x27;My first program runs&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Create hello.py, run it from a terminal, and change the output. If your system uses python3, run python3 --version and python3 hello.py.</p><p><strong>Learning check:</strong> Verify an interpreter and run a saved .py file.</p></section>\n</article>',2,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(177,31,'Python Syntax','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Python syntax includes valid statements, indentation, comments, and code structure. Learners practice correcting syntax errors.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Python uses indentation to show which statements belong together. A colon starts an indented block. Comments begin with # and are ignored by the interpreter.</p><h4>Worked example</h4><pre><code>temperature = 22\nif temperature &gt; 20:\n    print(&#x27;Warm day&#x27;)  # this line belongs to the if block\nelse:\n    print(&#x27;Cool day&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Introduce a syntax error by removing the colon, observe the error, then restore it. Add a comment explaining the condition.</p><p><strong>Learning check:</strong> Recognize a block and fix a simple syntax or indentation error.</p></section>\n</article>',3,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(178,31,'Variables & Constants','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Variables name values that can change; uppercase names are commonly used by convention for constants.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Assignment binds a name to an object. Names should describe their purpose and use lowercase words separated by underscores. Python does not enforce constants, but uppercase names communicate intent.</p><h4>Worked example</h4><pre><code>student_name = &#x27;Ari&#x27;\nscore = 8\nscore = score + 1\nPASSING_SCORE = 7\nprint(f&#x27;{student_name}: {score} (pass mark {PASSING_SCORE})&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Track a book title and page count. Update the page count and define MAX_PAGES in uppercase.</p><p><strong>Learning check:</strong> Assign, update, and name values clearly.</p></section>\n</article>',4,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(179,31,'Data Types','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Common data types include integers, decimals, strings, and Boolean values. Values can be converted when appropriate.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A type determines which operations make sense for a value. Input from input() is text, so convert numeric text before doing arithmetic. Conversion can fail when text is not a valid number.</p><h4>Worked example</h4><pre><code>age_text = &#x27;18&#x27;\nage = int(age_text)\nprice = 4.50\nis_member = True\nprint(type(age), type(price), type(age_text), is_member)</code></pre></section>\n<section><h3>Try it</h3><p>Create one value of each common type, print each value and type, and convert the string &#x27;12&#x27; to an integer.</p><p><strong>Learning check:</strong> Identify common types and convert compatible values.</p></section>\n</article>',5,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(180,31,'Operators & Expressions','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Operators perform arithmetic and logical comparisons. Operator precedence controls the order of evaluation.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Parentheses make the intended order clear. Comparisons produce Boolean values, which can be combined with and, or, and not. Use // for floor division and % for the remainder.</p><h4>Worked example</h4><pre><code>total = 2 + 3 * 4\nclear_total = (2 + 3) * 4\nprint(total, clear_total)\nprint(17 % 5, 17 // 5)\nprint(total &gt; 10 and clear_total == 20)</code></pre></section>\n<section><h3>Try it</h3><p>Calculate a subtotal for three items, apply a discount only when a Boolean condition is true, and print the result.</p><p><strong>Learning check:</strong> Predict expression results and use parentheses to make intent clear.</p></section>\n</article>',6,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(181,31,'Input & Output','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Programs receive information with input(), display results with print(), and can format strings.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>input() always returns a string. Convert it before arithmetic, and give users a clear prompt. An f-string inserts expressions inside braces.</p><h4>Worked example</h4><pre><code>name = input(&#x27;Name: &#x27;)\ncount = int(input(&#x27;How many books? &#x27;))\nprint(f&#x27;{name} has {count} book(s).&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Ask for two numbers and print their sum with a sentence. Try non-numeric input and explain what needs validation.</p><p><strong>Learning check:</strong> Read text, convert numeric input, and format output.</p></section>\n</article>',7,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(182,31,'Conditional Statements','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>if, elif, and else choose actions. Conditions can use comparisons and Boolean logic.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Python checks conditions from top to bottom and runs the first matching branch. Put the most specific or highest-priority cases first, and keep each branch focused.</p><h4>Worked example</h4><pre><code>score = 82\nif score &gt;= 90:\n    grade = &#x27;A&#x27;\nelif score &gt;= 75:\n    grade = &#x27;Pass&#x27;\nelse:\n    grade = &#x27;Review&#x27;\nprint(grade)</code></pre></section>\n<section><h3>Try it</h3><p>Classify a temperature as cold, comfortable, or hot. Test values at each boundary and explain the chosen branch.</p><p><strong>Learning check:</strong> Write and test a multi-branch decision.</p></section>\n</article>',8,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(183,31,'Loops & Iteration','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>for and while repeat work. range(), break, and continue help control loops.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Use for when iterating over a sequence or a known range. Use while when repetition depends on a condition, and make sure that condition can eventually become false.</p><h4>Worked example</h4><pre><code>for number in range(1, 6):\n    if number == 3:\n        continue\n    print(number)\n\nremaining = 3\nwhile remaining &gt; 0:\n    print(&#x27;Remaining:&#x27;, remaining)\n    remaining -= 1</code></pre></section>\n<section><h3>Try it</h3><p>Print the even numbers from 2 through 20, then use a while loop to count down from five to one.</p><p><strong>Learning check:</strong> Choose a loop and trace how its values change.</p></section>\n</article>',9,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(184,31,'Functions','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Functions package reusable instructions. They may accept parameters and return results; names and variables have scope.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A function should have one clear job. Parameters are local names provided by the caller. return sends a result back; print only displays it. Prefer explicit inputs and outputs over hidden global state.</p><h4>Worked example</h4><pre><code>def rectangle_area(width, height):\n    return width * height\n\narea = rectangle_area(4, 3)\nprint(area)</code></pre></section>\n<section><h3>Try it</h3><p>Write a function that converts minutes to seconds. Call it with two different inputs and test zero.</p><p><strong>Learning check:</strong> Define, call, and test a function with parameters and a return value.</p></section>\n</article>',10,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(185,31,'Strings & Text Processing','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Strings hold text. Methods support searching, formatting, and modification; slicing selects part of a string.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Strings are immutable: methods return a new string instead of changing the original. Indexes start at zero, and a slice excludes its ending index. strip() is useful for cleaning user input.</p><h4>Worked example</h4><pre><code>raw = &#x27;  Python Basics  &#x27;\nclean = raw.strip()\nprint(clean.lower())\nprint(clean[0:6])\nprint(clean.replace(&#x27;Basics&#x27;, &#x27;Practice&#x27;))</code></pre></section>\n<section><h3>Try it</h3><p>Ask for a sentence, trim its outer spaces, count its characters, and print it in lowercase.</p><p><strong>Learning check:</strong> Use indexes, slices, and string methods without expecting mutation.</p></section>\n</article>',11,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(186,31,'Lists','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Lists store ordered values that can be changed. Learners practice indexing, slicing, and adding or removing items.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A list keeps items in order and can contain different values, though related values are often easier to process. append adds one item, pop removes and returns one, and slices create a selected sequence.</p><h4>Worked example</h4><pre><code>tasks = [&#x27;read&#x27;, &#x27;practice&#x27;, &#x27;review&#x27;]\ntasks.append(&#x27;rest&#x27;)\nprint(tasks[0], tasks[1:3])\nfinished = tasks.pop(0)\nprint(f&#x27;Finished: {finished}; remaining: {tasks}&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Start with three chores, add a fourth, remove one completed chore, and print the final list.</p><p><strong>Learning check:</strong> Read and modify a list by index and common methods.</p></section>\n</article>',12,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(187,31,'Tuples & Sets','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Tuples are ordered collections whose elements cannot be reassigned. Sets contain unique values and support union and intersection.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Use a tuple for a small fixed group of related values, such as coordinates. Use a set when uniqueness or membership checks matter. Sets have no positional order to rely on.</p><h4>Worked example</h4><pre><code>point = (3, 5)\nattended = {&#x27;Ana&#x27;, &#x27;Bo&#x27;, &#x27;Ana&#x27;}\nsubmitted = {&#x27;Bo&#x27;, &#x27;Cy&#x27;}\nprint(point)\nprint(attended | submitted)  # union\nprint(attended &amp; submitted)  # intersection</code></pre></section>\n<section><h3>Try it</h3><p>Create two sets of learners who joined two sessions. Print everyone who attended and those who attended both.</p><p><strong>Learning check:</strong> Choose a tuple or set based on whether order, immutability, or uniqueness matters.</p></section>\n</article>',13,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(188,31,'Dictionaries','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Dictionaries store key-value pairs. Keys locate values; records can be created, updated, and retrieved.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A dictionary is useful when values have named roles. Keys must be unique and hashable. get() can provide a fallback for an optional key without raising KeyError.</p><h4>Worked example</h4><pre><code>student = {&#x27;name&#x27;: &#x27;Mina&#x27;, &#x27;score&#x27;: 91}\nstudent[&#x27;score&#x27;] += 4\nstudent[&#x27;passed&#x27;] = student[&#x27;score&#x27;] &gt;= 75\nprint(student.get(&#x27;name&#x27;, &#x27;Unknown&#x27;))\nprint(student)</code></pre></section>\n<section><h3>Try it</h3><p>Create a book record with title, author, and year. Add a borrowed Boolean and safely read an optional due_date.</p><p><strong>Learning check:</strong> Create, update, and safely retrieve dictionary values.</p></section>\n</article>',14,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(189,31,'Nested Data Structures','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Collections can contain other collections to represent records with multiple values. Learners access nested values and use comprehensions to transform data.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A list of dictionaries is a common way to represent rows of records. Read one level at a time, and use a comprehension when a simple transformation is clearer than a manual loop.</p><h4>Worked example</h4><pre><code>students = [{&#x27;name&#x27;: &#x27;Kai&#x27;, &#x27;score&#x27;: 80}, {&#x27;name&#x27;: &#x27;Lee&#x27;, &#x27;score&#x27;: 95}]\npassed_names = [s[&#x27;name&#x27;] for s in students if s[&#x27;score&#x27;] &gt;= 75]\nprint(passed_names)</code></pre></section>\n<section><h3>Try it</h3><p>Add a third student. Build a list of names with scores above 85 and compute the average score.</p><p><strong>Learning check:</strong> Navigate nested collections and create a filtered list.</p></section>\n</article>',15,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(190,32,'Modules & Packages','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Modules organize reusable code in separate files; packages group related modules. Learners import standard-library tools and organize programs.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A module is a Python file. Import only the names you need, and keep reusable code separate from the script that starts the program. A package groups modules under a directory.</p><h4>Worked example</h4><pre><code>from pathlib import Path\n\nnotes = Path(&#x27;notes.txt&#x27;)\nprint(f&#x27;File name: {notes.name}&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Move a helper function into helpers.py and import it from main.py. Also use pathlib to display a file name.</p><p><strong>Learning check:</strong> Import a standard-library module and describe a simple project layout.</p></section>\n</article>',1,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(191,32,'File Handling','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Programs can read and save information. Use open() and with to process files and close them safely.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>The with statement closes a file even if an error occurs. Choose an encoding for text files. Modes such as &#x27;r&#x27;, &#x27;w&#x27;, and &#x27;a&#x27; have different effects; &#x27;w&#x27; replaces existing content.</p><h4>Worked example</h4><pre><code>from pathlib import Path\n\npath = Path(&#x27;practice.txt&#x27;)\nwith path.open(&#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as file:\n    file.write(&#x27;First line\\n&#x27;)\nwith path.open(encoding=&#x27;utf-8&#x27;) as file:\n    print(file.read())</code></pre></section>\n<section><h3>Try it</h3><p>Append a second line, then read the file and count its lines. Explain why write mode can overwrite content.</p><p><strong>Learning check:</strong> Read and write a text file using a context manager and encoding.</p></section>\n</article>',2,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(192,32,'Exception Handling','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Exceptions signal runtime problems. try and except handle expected errors; learners read messages and debug issues.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Handle errors you can respond to, such as invalid numeric input or a missing file. Keep the try block small and avoid catching every exception, which can hide bugs.</p><h4>Worked example</h4><pre><code>text = &#x27;not a number&#x27;\ntry:\n    quantity = int(text)\nexcept ValueError:\n    print(&#x27;Please provide a whole number.&#x27;)\nelse:\n    print(quantity * 2)</code></pre></section>\n<section><h3>Try it</h3><p>Ask for a number and handle invalid input with a helpful message. Add a valid case that prints its square.</p><p><strong>Learning check:</strong> Identify an exception type and handle an expected failure.</p></section>\n</article>',3,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(193,32,'Recursion','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Recursion occurs when a function calls itself. A base case stops further calls; compare recursive solutions with loops.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Each recursive call should move toward a base case. Calls use memory, so recursion is best for naturally nested structures or teaching problem decomposition, not automatically better than a loop.</p><h4>Worked example</h4><pre><code>def countdown(number):\n    if number &lt;= 0:  # base case\n        return\n    print(number)\n    countdown(number - 1)\n\ncountdown(3)</code></pre></section>\n<section><h3>Try it</h3><p>Write a recursive function that sums positive integers down to zero. Trace the calls for input 3 before running it.</p><p><strong>Learning check:</strong> Point out the recursive step and base case, then trace a small input.</p></section>\n</article>',4,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(194,32,'Algorithms','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Algorithms are step-by-step problem-solving procedures. The proposal introduces searching, sorting, and comparing efficiency.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A linear search checks items one by one and takes time proportional to the list length. Sorting can make repeated searches easier. First choose a correct, readable approach, then measure performance if needed.</p><h4>Worked example</h4><pre><code>def find_index(items, target):\n    for index, item in enumerate(items):\n        if item == target:\n            return index\n    return -1\n\nprint(find_index([4, 8, 2], 8))</code></pre></section>\n<section><h3>Try it</h3><p>Modify the search to return every matching index. Compare its steps for lists of different lengths.</p><p><strong>Learning check:</strong> Describe an algorithm as steps and estimate how work grows with input size.</p></section>\n</article>',5,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(195,32,'Object-Oriented Programming','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>OOP groups related data and behavior in classes and objects. Learners create classes and instances.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A class describes a kind of object; an instance is one concrete object. Put behavior near the data it uses, while keeping a small example simple enough to understand.</p><h4>Worked example</h4><pre><code>class Counter:\n    def increment(self):\n        self.value += 1\n\nfirst = Counter()\nfirst.value = 0\nfirst.increment()\nprint(first.value)</code></pre></section>\n<section><h3>Try it</h3><p>Create a Book class with a method that prints a short description. Make two instances with different data.</p><p><strong>Learning check:</strong> Distinguish a class from its instances and call an instance method.</p></section>\n</article>',6,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(196,32,'Constructors','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>The __init__ method initializes instance attributes when an object is created.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Python calls __init__ after allocating a new instance. Store each object&#x27;s starting state there so every instance is valid immediately after construction.</p><h4>Worked example</h4><pre><code>class Counter:\n    def __init__(self, start=0):\n        self.value = start\n\n    def increment(self):\n        self.value += 1\n\nfirst = Counter(3)\nfirst.increment()\nprint(first.value)</code></pre></section>\n<section><h3>Try it</h3><p>Add a label parameter with a default and create two counters. Confirm changing one does not change the other.</p><p><strong>Learning check:</strong> Initialize instance state with __init__ and default arguments.</p></section>\n</article>',7,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(197,32,'OOP Principles','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>OOP principles include inheritance, encapsulation, polymorphism, and abstraction. Learners extend classes and override methods.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Inheritance can share a clear common interface, but deep class trees are hard to change. Polymorphism lets different objects respond to the same method call. Keep internal state behind methods when that helps protect invariants.</p><h4>Worked example</h4><pre><code>class Notifier:\n    def send(self, message):\n        raise NotImplementedError\n\nclass ConsoleNotifier(Notifier):\n    def send(self, message):\n        print(f&#x27;Notice: {message}&#x27;)\n\nfor notifier in [ConsoleNotifier()]:\n    notifier.send(&#x27;Ready&#x27;)</code></pre></section>\n<section><h3>Try it</h3><p>Create EmailNotifier and ConsoleNotifier with the same send(message) method. Call both through a shared list.</p><p><strong>Learning check:</strong> Explain method overriding and use a shared interface for different object types.</p></section>\n</article>',8,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(198,32,'Advanced Python Tools','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Iterators return values one at a time; generators produce sequences without storing all values. Decorators and context managers support reusable behavior.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A generator pauses at yield and resumes when requested, so it can process a large sequence incrementally. A context manager reliably performs setup and cleanup around a block.</p><h4>Worked example</h4><pre><code>def squares(limit):\n    for number in range(limit):\n        yield number * number\n\nfor value in squares(4):\n    print(value)</code></pre></section>\n<section><h3>Try it</h3><p>Write a generator that yields only even numbers below a limit. Name a file or resource that should be managed with a context manager.</p><p><strong>Learning check:</strong> Describe lazy iteration and write a small generator.</p></section>\n</article>',9,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(199,32,'Functional Programming','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Functions can be values and passed around. The slides introduce lambda, map(), filter(), and comprehensions.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A lambda is best for a short expression. For many transformations, a named function or comprehension can be easier to read. map and filter return iterators in Python 3.</p><h4>Worked example</h4><pre><code>prices = [10, 20, 30]\nwith_tax = [price * 1.12 for price in prices]\nlarge = list(filter(lambda price: price &gt;= 20, with_tax))\nprint(large)</code></pre></section>\n<section><h3>Try it</h3><p>Use a comprehension to square positive numbers, then compare its readability with map().</p><p><strong>Learning check:</strong> Transform or filter a collection and choose the clearest expression.</p></section>\n</article>',10,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(200,32,'Regex & Date/Time','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Regular expressions find text patterns. Date and time tools format dates and calculate time differences.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Regex is useful for structured pattern checks, but simple string methods are easier for simple tasks. Use datetime objects for date arithmetic instead of comparing formatted text.</p><h4>Worked example</h4><pre><code>import re\nfrom datetime import date\n\nmatch = re.fullmatch(r&#x27;[A-Z]{2}-\\d{4}&#x27;, &#x27;AB-2048&#x27;)\ndays = (date(2025, 1, 10) - date(2025, 1, 1)).days\nprint(bool(match), days)</code></pre></section>\n<section><h3>Try it</h3><p>Validate an ID shaped like two uppercase letters, a hyphen, and four digits. Calculate the days between two dates.</p><p><strong>Learning check:</strong> Use a pattern match for structured text and date objects for date calculations.</p></section>\n</article>',11,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(201,32,'Package Management','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>pip installs libraries. Virtual environments isolate each project&#x27;s dependencies.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A virtual environment gives a project its own interpreter environment and installed packages. Record direct dependencies so another developer can reproduce the setup. Do not install a package just because its name looks familiar; check its source.</p><h4>Worked example</h4><pre><code># Run these commands in a terminal, from your project folder:\npython -m venv .venv\n# Activate the environment for your operating system\npython -m pip install requests\npython -m pip freeze &gt; requirements.txt</code></pre></section>\n<section><h3>Try it</h3><p>Create an environment for a sample project, install one package, and save its requirements. Explain how to recreate the environment.</p><p><strong>Learning check:</strong> Create an isolated environment and record dependencies.</p></section>\n</article>',12,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(202,33,'Database Integration','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Databases store structured data. The slides introduce SQL SELECT and INSERT and connecting Python to a sample database.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Use parameterized SQL for values instead of building queries with string concatenation. This SQLite example uses Python&#x27;s standard library and an in-memory database, so it does not need an external service.</p><h4>Worked example</h4><pre><code>import sqlite3\n\nwith sqlite3.connect(&#x27;:memory:&#x27;) as connection:\n    connection.execute(&#x27;CREATE TABLE tasks (name TEXT, done INTEGER)&#x27;)\n    connection.execute(&#x27;INSERT INTO tasks VALUES (?, ?)&#x27;, (&#x27;read&#x27;, 0))\n    rows = connection.execute(&#x27;SELECT name, done FROM tasks&#x27;).fetchall()\n    print(rows)</code></pre></section>\n<section><h3>Try it</h3><p>Add a second record, query all records, and change one value using an UPDATE statement with placeholders.</p><p><strong>Learning check:</strong> Create, insert, and query a small table using parameterized statements.</p></section>\n</article>',1,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(203,33,'APIs & Web Data','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>APIs let programs exchange data. The slides introduce HTTP requests, JSON responses, and a controlled example API.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>An HTTP response has a status and a body. JSON values map to Python dictionaries and lists. Check status and validate the shape of external data before using it; this example parses a fixed response without needing network access.</p><h4>Worked example</h4><pre><code>import json\n\npayload = &#x27;{&quot;name&quot;: &quot;Ada&quot;, &quot;active&quot;: true}&#x27;\ndata = json.loads(payload)\nprint(data[&#x27;name&#x27;], data[&#x27;active&#x27;])\nprint(json.dumps(data, indent=2))</code></pre></section>\n<section><h3>Try it</h3><p>Parse a JSON list of two books and print each title. Then identify which checks a real HTTP client should make before trusting a response.</p><p><strong>Learning check:</strong> Decode JSON and describe status/error handling for a real request.</p></section>\n</article>',2,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(204,33,'Testing & Deployment','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Tests check expected behavior and uncover problems. The slides ask learners to prepare a small project for presentation or delivery.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A unit test checks one behavior with known inputs and expected outputs. Tests are executable documentation. Deployment also needs a reproducible environment, clear startup steps, and configuration kept outside source code.</p><h4>Worked example</h4><pre><code>import unittest\n\ndef double(value):\n    return value * 2\n\nclass DoubleTests(unittest.TestCase):\n    def test_positive_number(self):\n        self.assertEqual(double(4), 8)\n\nif __name__ == &#x27;__main__&#x27;:\n    unittest.main()</code></pre></section>\n<section><h3>Try it</h3><p>Add tests for zero and a negative number. Write short run instructions for a classmate who has not seen the project.</p><p><strong>Learning check:</strong> Write tests for normal and edge cases and prepare repeatable run instructions.</p></section>\n</article>',3,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(205,33,'Python Graphs','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Graphs show relationships and trends. The slides use Matplotlib for line graphs and scatter plots, with axis labels and titles.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>Choose a line plot when values are ordered, often over time. A scatter plot is useful for relationships between paired measurements. Labels and units help readers interpret a chart.</p><h4>Worked example</h4><pre><code>import matplotlib.pyplot as plt\n\ndays = [1, 2, 3, 4]\ntemperature = [20, 22, 21, 25]\nplt.plot(days, temperature, marker=&#x27;o&#x27;)\nplt.xlabel(&#x27;Day&#x27;)\nplt.ylabel(&#x27;Temperature (°C)&#x27;)\nplt.title(&#x27;Temperature by day&#x27;)\nplt.show()</code></pre></section>\n<section><h3>Try it</h3><p>Change the data and create a scatter plot. Add units and explain one trend the chart shows.</p><p><strong>Learning check:</strong> Select a line or scatter graph and label its axes and title.</p></section>\n</article>',4,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL),(206,33,'Python Charts','<article class=\"python-lesson\">\n<section class=\"source-outline\"><h3>Course proposal outline</h3><p>Summary of the topic described in MADERA_SAM_PROPOSAL.PPTX:</p><p>Charts compare categories, proportions, and distributions. The slides mention bar charts, pie charts, histograms, Seaborn, Plotly, and Pandas plotting.</p></section>\n<section><h3>Teaching material authored for this module</h3><p>A bar chart compares separate categories; a histogram shows a numeric distribution. Pie charts work best for a small number of parts that add to a meaningful whole. Seaborn, Plotly, and Pandas provide additional plotting interfaces.</p><h4>Worked example</h4><pre><code>import matplotlib.pyplot as plt\n\nlabels = [&#x27;Books&#x27;, &#x27;Games&#x27;, &#x27;Music&#x27;]\ncounts = [5, 3, 4]\nplt.bar(labels, counts)\nplt.ylabel(&#x27;Items&#x27;)\nplt.title(&#x27;Items by category&#x27;)\nplt.show()</code></pre></section>\n<section><h3>Try it</h3><p>Build a histogram from a short list of quiz scores. Choose a chart type for comparing three categories and explain why it fits.</p><p><strong>Learning check:</strong> Match a chart type to comparison or distribution and label it clearly.</p></section>\n</article>',5,'2026-10-26 15:55:11','2026-10-26 15:55:11',NULL,NULL,NULL);
