INSERT INTO `topics` VALUES (1,'HISTORY AND EVOLUTION OF UNIX, GNU & LINUX','Complete lesson covering history and evolution of unix, gnu & linux.',1,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(2,'OPERATING SYSTEM, LINUX PLATFORM & SYSTEM FOUNDATIONS','Complete lesson covering operating system, linux platform & system foundations.',2,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(3,'LINUX KERNEL EVOLUTION, MAJOR RELEASES & PLATFORM CAPABILITIES','Complete lesson covering linux kernel evolution, major releases & platform capabilities.',3,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(4,'KERNEL ARCHITECTURE, SYSTEM LAYERS, RESOURCE MANAGEMENT & KERNEL TYPES','Complete lesson covering kernel architecture, system layers, resource management & kernel types.',4,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(5,'GNU/LINUX, OPEN SOURCE SOFTWARE, LICENSING & SOFTWARE FREEDOM','Complete lesson covering gnu/linux, open source software, licensing & software freedom.',5,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(6,'LINUX DISTRIBUTIONS, FAMILIES, PLATFORMS & ECOSYSTEM','Complete lesson covering linux distributions, families, platforms & ecosystem.',6,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(7,'LINUX USER ENVIRONMENTS: DESKTOPS, DISPLAY SERVERS & DISPLAY MANAGERS','Complete lesson covering linux user environments: desktops, display servers & display managers.',7,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(8,'LINUX INSTALLATION, BOOT ARCHITECTURE, BOOT LOADERS & SYSTEM REQUIREMENTS','Complete lesson covering linux installation, boot architecture, boot loaders & system requirements.',8,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(9,'LINUX STORAGE, FILESYSTEMS, JOURNALING & DATA ORGANIZATION','Complete lesson covering linux storage, filesystems, journaling & data organization.',9,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(10,'LINUX DIRECTORY HIERARCHY, SYSTEM PATHS & FILE ORGANIZATION','Complete lesson covering linux directory hierarchy, system paths & file organization.',10,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(11,'LINUX SHELLS, TERMINAL ENVIRONMENT & COMMAND-LINE INTERACTION','Complete lesson covering linux shells, terminal environment & command-line interaction.',11,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(12,'LINUX NAVIGATION, PATHS, DIRECTORIES & BASIC FILESYSTEM OPERATIONS','Complete lesson covering linux navigation, paths, directories & basic filesystem operations.',12,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(13,'LINUX FILE OPERATIONS, CONTENT VIEWING, OUTPUT & TEXT HANDLING','Complete lesson covering linux file operations, content viewing, output & text handling.',13,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(14,'LINUX USERS, GROUPS, ACCOUNTS & IDENTITY ADMINISTRATION','Complete lesson covering linux users, groups, accounts & identity administration.',14,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(15,'LINUX SEARCH, FILTERS, UTILITIES, ARCHIVING, COMPRESSION & LINKS','Complete lesson covering linux search, filters, utilities, archiving, compression & links.',15,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(16,'LINUX NETWORKING COMMANDS, CONNECTIVITY, NAME RESOLUTION & REMOTE ACCESS','Complete lesson covering linux networking commands, connectivity, name resolution & remote access.',16,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(17,'LINUX PERMISSIONS, OWNERSHIP, ACCESS MODES & FILE SECURITY','Complete lesson covering linux permissions, ownership, access modes & file security.',17,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(18,'ADMINISTRATIVE PRIVILEGES, SUDO, ROOT ACCESS & SECURE PRIVILEGE MANAGEMENT','Complete lesson covering administrative privileges, sudo, root access & secure privilege management.',18,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(19,'LINUX SERVER INSTALLATION, HOST IDENTITY, IP CONFIGURATION & NETWORK SETUP','Complete lesson covering linux server installation, host identity, ip configuration & network setup.',19,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(20,'SERVER FUNDAMENTALS, CLIENT-SERVER COMPUTING & NETWORK SERVER ARCHITECTURE','Complete lesson covering server fundamentals, client-server computing & network server architecture.',20,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(21,'SERVER TYPES, ROLES, SERVICES, PLATFORMS & ENTERPRISE SERVER CONCEPTS','Complete lesson covering server types, roles, services, platforms & enterprise server concepts.',21,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(22,'SOFTWARE INSTALLATION, PACKAGE MANAGEMENT, REPOSITORIES & APPLICATION DEPLOYMENT','Complete lesson covering software installation, package management, repositories & application deployment.',22,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(23,'WEB SERVERS, APACHE, LAMP STACK & BASIC WEB APPLICATION HOSTING','Complete lesson covering web servers, apache, lamp stack & basic web application hosting.',23,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(24,'NETWORK SERVICES: SSH, FTP, DHCP & LINUX SERVICE MANAGEMENT','Complete lesson covering network services: ssh, ftp, dhcp & linux service management.',24,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(25,'CYBERSECURITY, ETHICAL HACKING, HACKER CLASSIFICATIONS & ATTACK TARGETS','Complete lesson covering cybersecurity, ethical hacking, hacker classifications & attack targets.',25,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(26,'ETHICAL HACKING LIFECYCLE, PHASES, PENETRATION TESTING METHODOLOGY & REPORTING','Complete lesson covering ethical hacking lifecycle, phases, penetration testing methodology & reporting.',26,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(27,'RECONNAISSANCE, FOOTPRINTING, FINGERPRINTING & TARGET PROFILING','Complete lesson covering reconnaissance, footprinting, fingerprinting & target profiling.',27,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(28,'INFORMATION GATHERING, NETWORK DISCOVERY, OSINT & VULNERABILITY ASSESSMENT TOOLS','Complete lesson covering information gathering, network discovery, osint & vulnerability assessment tools.',28,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(29,'EXPLOITATION, WEB PENETRATION TESTING, KALI LINUX & SECURITY TOOLSETS','Complete lesson covering exploitation, web penetration testing, kali linux & security toolsets.',29,'2026-10-21 23:30:24','2026-10-21 23:56:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'system_administration'),(30,'ETHICAL HACKING LABS, LINUX SERVER HARDENING & DEFENSIVE